import { after } from 'next/server'
import { revalidateTag } from 'next/cache'
import { syncCatalogFromErp } from '@/lib/db'
import { getCachedCatalogMeta, getCachedProducts } from '@/lib/products'

function formatSyncedAt(timestamp: number | null) {
  if (timestamp === null) return 'Never synced'
  return new Intl.DateTimeFormat('en-US', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(timestamp))
}

function formatPrice(price: number) {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(price)
}

export default async function AdminCatalogPage() {
  const [products, meta] = await Promise.all([
    getCachedProducts(),
    getCachedCatalogMeta(),
  ])

  async function syncLatestCatalog() {
    'use server'

    after(async () => {
      await syncCatalogFromErp()
      revalidateTag('products', 'max')
    })
  }

